VALUES (238169, 'tt0246986', NULL, 'Thiruvilayadal', 'திருவிளையாடல்', 'movie', 1965, 'https://image.tmdb.org/t/p/w500/AcGmbZdQqUBiXgAZmfnHf77m22j.jpg', 'https://image.tmdb.org/t/p/original/vr7lNT9PHxTU5EqP9eCcdpYjC6R.jpg', 'The Hindu god Shiva gives a sacred mango fruit, brought by the sage Narada, to his elder son Vinayaka as a prize for outsmarting his younger brother Muruga in a competition. Angry with his father, Muruga leaves home for Palani. He meets Avvaiyar, one of his devotees, along the way. Despite her attempts to convince Muruga to return to Mount Kailash, he remains adamant about his decision to leave his family. His mother, the goddess Parvati, arrives there and tells the stories of four of Shiva''s divine games to calm Muruga.', NULL, NULL, 1.1185, 7.6, 0, 10.02, '2026-10-16 22:59:46', '2026-10-16 22:59:46')
