VALUES (11665, 'tt0425061', NULL, 'Get Smart', 'Get Smart', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/sZUjbtUS8qxXp4mj90evnqPJqX7.jpg', 'https://image.tmdb.org/t/p/original/u0yaNgikY92zkI0t3fiEGZP3UWq.jpg', 'When members of the nefarious crime syndicate KAOS attack the U.S. spy agency Control and the identities of secret agents are compromised, the Chief has to promote hapless but eager analyst Maxwell Smart to field agent. He is partnered with veteran and capable Agent 99, the only spy whose cover remains intact. Can they work together to thwart the evil world-domination plans of KAOS and its crafty operative?', NULL, NULL, 10.1469, 6.221, 0, 8.01, '2026-10-16 22:59:46', '2026-10-16 22:59:46')
