VALUES (57283, 'tt0013257', NULL, 'Häxan', 'Häxan', 'movie', 1922, 'https://image.tmdb.org/t/p/w500/3LtaPLlwlA5HX2FjqAb8lsaBI8P.jpg', 'https://image.tmdb.org/t/p/original/gZwQip2KQRDNZZOEDe0Yi25tW9Z.jpg', 'Grave robbing, torture, possessed nuns, and a satanic Sabbath: Benjamin Christensen''s legendary film uses a series of dramatic vignettes to explore the scientific hypothesis that the witches of the Middle Ages suffered the same hysteria as turn-of-the-century psychiatric patients. But the film itself is far from serious-- instead it''s a witches'' brew of the scary, gross, and darkly humorous.', NULL, NULL, 1.6868, 7.6, 0, 2.56560869565217402e+01, '2026-07-15 12:01:52', '2026-10-16 22:59:46')
