VALUES (11314, 'tt0085809', NULL, 'Koyaanisqatsi', 'Koyaanisqatsi', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/6zCNciRcob8lwuydVXgq0esla8L.jpg', 'https://image.tmdb.org/t/p/original/84E96lyR81OvUjCimcrfuzn9er5.jpg', 'Takes us to locations all around the US and shows us the heavy toll that modern technology is having on humans and the earth. The visual tone poem contains neither dialogue nor a vocalized narration: its tone is set by the juxtaposition of images and the exceptional music by Philip Glass.', NULL, NULL, 3.0242, 7.881, 0, 20.976, '2026-07-15 12:01:52', '2026-10-16 22:59:46')
