VALUES (36819, 'tt0081633', NULL, 'Time Bandits', 'Time Bandits', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/4VZtpwdhHQSa4LUkvujyGAHb1hG.jpg', 'https://image.tmdb.org/t/p/original/qKERrt3UU1ml8Q9zdsLPpoQ5r3.jpg', 'Young history buff Kevin can scarcely believe it when six dwarfs emerge from his closet one night. Former employees of the Supreme Being, they''ve purloined a map charting all of the holes in the fabric of time and are using it to steal treasures from different historical eras. Taking Kevin with them, they variously drop in on Napoleon, Robin Hood and King Agamemnon before the Supreme Being catches up with them.', NULL, NULL, 3.5354, 6.626, 0, 3.84193939393939416e+01, '2026-07-15 12:01:52', '2026-10-16 22:59:46')
