VALUES (2024, 'tt0187393', NULL, 'The Patriot', 'The Patriot', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/fWZd815QxUCUcrWQZwUkAp9ljG.jpg', 'https://image.tmdb.org/t/p/original/kWYHKVCl2aD3kRco4eRUr4h6LsD.jpg', 'After proving himself on the field of battle in the French and Indian War, Benjamin Martin wants nothing more to do with such things, preferring the simple life of a farmer. But when his son Gabriel enlists in the army to defend their new nation, America, against the British, Benjamin reluctantly returns to his old life to protect his son.', NULL, NULL, 9.5954, 7.211, 0, 13.873, '2026-07-20 01:02:04', '2026-10-16 22:59:46')
