VALUES (8741, 'tt0120863', NULL, 'The Thin Red Line', 'The Thin Red Line', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/seMydAaoxQP6F0xbE1jOcTmn5Jr.jpg', 'https://image.tmdb.org/t/p/original/hsDyfAk2ml82IrpPC4AHvxvuTsn.jpg', 'The story of a group of men, an Army Rifle company called C-for-Charlie, who change, suffer, and ultimately make essential discoveries about themselves during the fierce World War II battle of Guadalcanal. It follows their journey, from the surprise of an unopposed landing, through the bloody and exhausting battles that follow, to the ultimate departure of those who survived.', NULL, NULL, 6.609, 7.441, 0, 28.80375, '2026-07-20 04:02:06', '2026-10-16 22:59:46')
