VALUES (812583, 'tt14364480', NULL, 'Wake Up Dead Man: A Knives Out Mystery', 'Wake Up Dead Man: A Knives Out Mystery', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/qCOGGi8JBVEZMc3DVby8rUivyXz.jpg', 'https://image.tmdb.org/t/p/original/fiRDzpcJe7qz3yIR43hdXIE3NHv.jpg', 'When young priest Jud Duplenticy is sent to assist charismatic firebrand Monsignor Jefferson Wicks, it’s clear that all is not well in the pews. After a sudden and seemingly impossible murder rocks the town, the lack of an obvious suspect prompts local police chief Geraldine Scott to join forces with renowned detective Benoit Blanc to unravel a mystery that defies all logic.', NULL, NULL, 17.3172, 7.206, 0, 16.0125, '2026-07-21 03:32:24', '2026-10-16 22:59:46')
