VALUES (1389, 'tt0120780', NULL, 'Out of Sight', 'Out of Sight', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/v49q7AMR3pB4M762woWB1NYMCLF.jpg', 'https://image.tmdb.org/t/p/original/rOvXN8m3l4qNKCdNscLUjxK6I9I.jpg', 'Meet Jack Foley, a smooth criminal who bends the law and is determined to make one last heist. Karen Sisco is a federal marshal who chooses all the right moves … and all the wrong guys. Now they''re willing to risk it all to find out if there''s more between them than just the law.', NULL, NULL, 6.3783, 6.7, 0, 8.128, '2026-08-11 02:46:38', '2026-10-16 22:59:46')
