VALUES (19759, 'tt0052374', NULL, 'The Fabulous World of Jules Verne', 'Vynález zkázy', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/aJ9GqbghpkPJ4siOycoCXEdVC1u.jpg', 'https://image.tmdb.org/t/p/original/5fecahtvSbL4ZCMytkas7styNWb.jpg', 'As the world progresses into the industrial age, a professor studying the "nature of pure matter" is spirited away by a would-be dictator and connived into building a super-bomb, as a  young reporter and a girl rescued from the sea attempt to warn him of their mutual kidnapper''s intentions to dominate the world with a new and more-deadly-yet  weapon.', NULL, NULL, 2.456, 7.172, 0, 13.712, '2026-08-19 01:49:52', '2026-10-16 22:59:46')
