VALUES (336843, 'tt4500922', NULL, 'Maze Runner: The Death Cure', 'Maze Runner: The Death Cure', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/s8K0US4tUEoOrQ1LDh0eppuwGDx.jpg', 'https://image.tmdb.org/t/p/original/zGCfnZ3bCowMY9So9ZGpsyuOYl3.jpg', 'Thomas leads his group of escaped Gladers on their final and most dangerous mission yet. To save their friends, they must break into the legendary Last City, a WCKD-controlled labyrinth that may turn out to be the deadliest maze of all. Anyone who makes it out alive will get answers to the questions the Gladers have been asking since they first arrived in the maze.', NULL, NULL, 29.2273, 7.075, 0, 8.50999999999999801e+00, '2026-08-23 01:42:21', '2026-10-16 22:59:46')
